-- private.reach_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION private.reach_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_x double precision; v_y double precision; v_d action_def; v_most int := private.reach_most(); v_size int;
begin
  if p_target is null or coalesce(p_target->>'kind', 'tile') not in ('tile', 'ground') then return null; end if;
  select pl.x, pl.y, w.size into v_x, v_y, v_size from player pl join world w on w.id = pl.world_id
   where pl.world_id = p_world and pl.uid = p_uid;
  if v_x is null then return null; end if;
  -- A tile of the island only, its tile or its corner: one off it is nothing to reach, and each family says so in its own words.
  if private.far_off(v_x, v_y, p_target->'x', p_target->'y', v_size, v_most)
     or private.far_off(v_x, v_y, p_target->'cx', p_target->'cy', v_size, v_most) then
    return 'You are too far away from that.';
  end if;
  if not private.set_down_job(p_action) then return null; end if;
  if (p_target ? 'sx' and case when jsonb_typeof(p_target->'sx') = 'number'
                               then (p_target->>'sx')::numeric not between 0 and subtiles() - 1 else true end)
     or (p_target ? 'sy' and case when jsonb_typeof(p_target->'sy') = 'number'
                                  then (p_target->>'sy')::numeric not between 0 and subtiles() - 1 else true end) then
    return 'Choose a spot.';
  end if;
  select * into v_d from action_def where id = p_action;
  if in_reach(v_x, v_y, p_target, v_d.corner, v_d.range) is false then return 'You are too far away from that.'; end if;
  return null;
end $function$
